+            if (completion == Completion::Complete && sameIssuer)
+              return std::nullopt;
+            return advanceLifetime(state, node.op, access);
+          },
+          {},
+          [](Edge edge, unsigned state) {
+            return edge.invalidatesIteration ? state | carried : state;
+          });
+  }
+}
