+  cfg.nodes[2].next.push_back({4});
+  cfg.nodes[3].next.clear();
+  const Demand demands[] = {{1, 3, Need::RegionOrder},
+                            {1, 4, Need::RegionOrder}};
+  auto solution = solveMembarCut(cfg, demands);
+  ASSERT_TRUE(solution);
